CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_mark_as_bonified`(
    IN p_id   INT,
    IN p_type VARCHAR(50)
)
BEGIN
    IF p_type = 'appointment' THEN
        UPDATE transactions
        SET
            amount  = 0,
            method  = 'bonified',
            status  = 'paid'
        WHERE appointment_id = p_id;

        
        UPDATE appointments
        SET bonified = 1
        WHERE id = p_id;

    ELSEIF p_type = 'prescription' THEN
        
        UPDATE transactions
        SET
            amount  = 0,
            method  = 'bonified',
            status  = 'paid'
        WHERE request_id = p_id;

    END IF;
END
;;
DELIMITER ;
